create or replace function public.dashboard_monthly_unit_summary(month_start date)
returns table(unit_id uuid, body_number text, remittance_due_centavos bigint, remittance_paid_centavos bigint, outstanding_centavos bigint, total_expense_centavos bigint, net_income_centavos bigint)
language sql stable security definer set search_path=public as $$ select u.id,u.body_number,coalesce((select sum(r.amount_due_centavos) from remittances r where r.unit_id=u.id and r.service_date>=month_start and r.service_date<month_start+interval '1 month' and r.deleted_at is null),0),coalesce((select sum(p.amount_centavos) from remittance_payments p join remittances r on r.id=p.remittance_id where r.unit_id=u.id and r.service_date>=month_start and r.service_date<month_start+interval '1 month' and p.deleted_at is null),0),0,coalesce((select sum(e.amount_centavos) from expenses e where e.unit_id=u.id and e.expense_date>=month_start and e.expense_date<month_start+interval '1 month' and e.deleted_at is null),0),0 from units u where u.deleted_at is null and public.is_owner() $$;
